import{_ as t,o as d,c as o,a4 as a}from"./chunks/framework.DpieW3qv.js";const p=JSON.parse('{"title":"Command Reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/commands.md","filePath":"reference/commands.md","lastUpdated":null}'),r={name:"reference/commands.md"};function s(c,e,i,l,n,h){return d(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="command-reference" tabindex="-1">Command Reference <a class="header-anchor" href="#command-reference" aria-label="Permalink to &quot;Command Reference&quot;">​</a></h1><p>Quick reference for all Makefile commands. For full syntax, flags, and example output, use the per-command pages under <a href="/ocapi-docs.github.io/cli/">Commands</a>.</p><h2 id="command-summary" tabindex="-1">Command summary <a class="header-anchor" href="#command-summary" aria-label="Permalink to &quot;Command summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>make setup</code></td><td>Configure brand, data source, and SFCC (OCAPI). Runs a wizard and saves config.</td></tr><tr><td><code>make switch [BRAND=]</code></td><td>Toggle brand (no arg: loft ↔ ann). Or <code>make switch BRAND=ann</code> for specific brand.</td></tr><tr><td><code>make health</code></td><td>Test your SFCC connection.</td></tr><tr><td><code>make pull</code></td><td>Git pull, fetch latest data (Excel/Smartsheet), auto-build new dates, then open the status hub.</td></tr><tr><td><code>make preview</code></td><td>Build if needed (with change approval), compose previews, and open the file browser.</td></tr><tr><td><code>make push</code></td><td>Validate, sync to SFCC, generate changeout email, and staging URL; run <strong>make replicate</strong> for replication steps.</td></tr><tr><td><code>make commit</code></td><td>Save the selected refresh to Git (refresh dir only).</td></tr><tr><td><code>make status</code></td><td>Interactive hub: pick a refresh, choose an action (preview, push, commit, etc.), run it, then return to the board.</td></tr><tr><td><code>make browse</code></td><td>Browse data files for the active refresh (assets, refresh.json, payload).</td></tr><tr><td><code>make replicate</code></td><td>Print replication steps (staging → production).</td></tr><tr><td><code>make email</code></td><td>Generate the changeout email (also runs after <code>make push</code>).</td></tr><tr><td><code>make excel</code></td><td>Parse Excel into refresh data; does not build.</td></tr><tr><td><code>make delete DATE=</code></td><td>Remove a refresh from SFCC and locally. <strong>DATE= is required to delete;</strong> omit DATE (run <code>make delete</code> with no args) to list deletable refreshes. Use <code>REFRESH=r1</code> when the date has multiple refreshes.</td></tr><tr><td><code>make upload</code></td><td>Partial asset sync (HTML changes only).</td></tr><tr><td><code>make registry</code></td><td>Show the live asset registry (zones and item counts). Use <code>ARGS=&quot;--ipids&quot;</code> to list IPIDs.</td></tr><tr><td><code>make test</code></td><td>Run all tests. Use <code>test-watch</code> for watch mode, <code>test-coverage</code> for coverage, <code>test-brands</code> for E2E both brands.</td></tr><tr><td><code>make fresh-install</code></td><td>Full reset: remove dev-env and node_modules, reinstall, then run E2E.</td></tr><tr><td><code>make convert-excel INPUT=</code></td><td>Convert raw Excel to CONVERTED format (INPUT required).</td></tr><tr><td><code>make check</code></td><td>Lint, tests, and audit (CI gate).</td></tr><tr><td><code>make clean</code></td><td>Remove rendered previews.</td></tr><tr><td><code>make docs</code></td><td>Generate API docs and start the docs dev server.</td></tr><tr><td><code>make docs-gen</code></td><td>Regenerate API and template reference docs.</td></tr><tr><td><code>make docs-build</code></td><td>Generate docs and build the static site.</td></tr><tr><td><code>make docs-deploy</code></td><td>Build and deploy docs to GitHub Pages.</td></tr><tr><td><code>make lint-docs</code></td><td>Lint action types in doc files.</td></tr><tr><td><code>make reports [OP=dates]</code></td><td>Reports: dates, stats, status, pending, history. See <a href="/ocapi-docs.github.io/cli/reports.html">reports</a>.</td></tr><tr><td><code>make validate [DATE=]</code></td><td>Data quality check only (no build or push). See <a href="/ocapi-docs.github.io/cli/validate.html">validate</a>.</td></tr><tr><td><code>make test-sync DATE=</code></td><td>Push to OCAPI with auto-confirm (for CI).</td></tr><tr><td><code>make build-all [FORCE=1]</code></td><td>Build every date for the current brand.</td></tr><tr><td><code>make push-all [YES=1] [FORCE=1]</code></td><td>Sync every date to SFCC (run after build-all).</td></tr><tr><td><code>make config</code></td><td>Print current configuration (no secrets).</td></tr><tr><td><code>make doctor</code></td><td>Validate setup, config, brand, source, refresh dirs, and OCAPI env.</td></tr></tbody></table><p><strong>Test commands:</strong> Run <code>make test</code> for the full suite. Use <code>make test-watch</code> for watch mode, <code>make test-coverage</code> for coverage, and <code>make test-brands</code> for E2E both brands. Use <code>make fresh-install</code> for a full reset (deps + dev-env) then E2E. To run a subset by path: <code>npx vitest run tests/domain</code> or <code>npx vitest run tests/cli</code>.</p><p><strong>Approval guards:</strong> When data has already been built or synced and you run <code>make preview</code> or <code>make push</code> again, the tool shows what changed (copy, destinations, items added/removed) and asks for approval instead of blocking. Use <code>FORCE=1</code> to skip the prompt (e.g., in CI). Use <code>YES=1</code> to auto-approve.</p><p><strong>build-all / push-all:</strong> For dev/CI batch runs. Run <code>make pull</code> first (auto-builds new dates); then <code>make build-all</code> to rebuild all dates; then <code>make push-all</code> to sync all of them to SFCC. Use <code>YES=1</code> to skip confirmation prompts. Use <code>FAIL_FAST=1</code> to stop on first failure (default: continue on error).</p><p><strong>Automation:</strong> For scripts and CI, use <code>DATE=</code>, <code>REFRESH=</code>, <code>YES=1</code>, <code>FORCE=1</code> as needed. Use <code>VERBOSE=1</code> for run IDs on log lines. Use <code>FAIL_FAST=1</code> for fail-fast batch runs, and <code>ARGS=&quot;...&quot;</code> to pass extra CLI flags.</p><h2 id="make-variables-→-cli-flags" tabindex="-1">Make variables → CLI flags <a class="header-anchor" href="#make-variables-→-cli-flags" aria-label="Permalink to &quot;Make variables → CLI flags&quot;">​</a></h2><p>The Makefile is the source of truth. All commands are invoked via <code>make &lt;target&gt;</code>; the CLI receives variables as flags.</p><table tabindex="0"><thead><tr><th>Make variable</th><th>CLI flag / behaviour</th><th>Example</th></tr></thead><tbody><tr><td><code>BRAND</code></td><td>First positional arg (defaults to config brand); for <code>make switch</code>: target brand (omit to toggle)</td><td><code>make preview</code>; <code>make switch BRAND=ann</code></td></tr><tr><td><code>DATE</code></td><td><code>--date=YYYY-MM-DD</code></td><td><code>make preview DATE=2026-02-14</code></td></tr><tr><td><code>REFRESH</code></td><td><code>--refresh=r1</code></td><td><code>make push REFRESH=r2</code></td></tr><tr><td><code>FORCE=1</code></td><td><code>--force</code> (force rebuild/re-push; skip delete confirmation)</td><td><code>make push FORCE=1</code>; <code>make delete DATE=… FORCE=1</code></td></tr><tr><td><code>YES=1</code></td><td><code>--yes</code> (skip confirmation/approval prompts)</td><td><code>make push-all YES=1</code></td></tr><tr><td><code>ALL=1</code></td><td><code>preview</code>/<code>push</code>: <code>--all-refreshes</code> (all refreshes in a date); <code>status</code>: <code>--all</code> (full history)</td><td><code>make status ALL=1</code></td></tr><tr><td><code>FAIL_FAST=1</code></td><td>Stop <code>build-all</code>/<code>push-all</code> on first failure (default: continue)</td><td><code>make build-all FAIL_FAST=1</code></td></tr><tr><td><code>ARGS=&quot;...&quot;</code></td><td>Pass extra CLI flags (appended after mapped vars)</td><td><code>make push ARGS=&quot;--yes --force&quot;</code></td></tr><tr><td><code>SKIP_FETCH=1</code></td><td><code>--skip-fetch</code></td><td><code>make pull SKIP_FETCH=1</code></td></tr><tr><td><code>CONVERT=1</code></td><td><code>--convert</code></td><td><code>make pull CONVERT=1</code></td></tr><tr><td><code>STATUS_REFRESH_INDEX</code></td><td>status (non-TTY): 0-based index of refresh row to act on</td><td><code>STATUS_REFRESH_INDEX=2 make status</code></td></tr><tr><td><code>STATUS_ACTION_INDEX</code></td><td>status (non-TTY): 0-based index of action (0=Preview/Browse, 1=Push, 2=Commit, 3=Force rebuild, 4=Email, 5=View data quality, 6=Pull)</td><td><code>STATUS_ACTION_INDEX=1 make status</code></td></tr><tr><td><code>VERBOSE=1</code></td><td><code>--verbose</code></td><td><code>make push VERBOSE=1</code></td></tr><tr><td><code>COPY=1</code></td><td><code>--copy</code></td><td><code>make email COPY=1</code></td></tr><tr><td><code>OP</code></td><td>reports operation (dates, stats, status, pending, history)</td><td><code>make reports OP=stats</code> (default: dates)</td></tr></tbody></table><p><strong>Brand switch:</strong> Use <code>make switch</code> to toggle loft ↔ ann (no args). Use <code>make switch BRAND=ann</code> for a specific brand. Use <code>make setup</code> for full wizard.</p><h2 id="shared-cli-flags" tabindex="-1">Shared CLI flags <a class="header-anchor" href="#shared-cli-flags" aria-label="Permalink to &quot;Shared CLI flags&quot;">​</a></h2><p>Most commands support: <code>--force</code>, <code>-y/--yes</code>, <code>--dry-run</code>, <code>--verbose</code>, <code>--date</code>, <code>--refresh</code>, <code>--no-interactive</code>, <code>--strict</code>. See per-command pages for command-specific flags. Run <code>make &lt;command&gt; ARGS=&quot;--help&quot;</code> for full usage.</p><h2 id="cli-arguments" tabindex="-1">CLI arguments <a class="header-anchor" href="#cli-arguments" aria-label="Permalink to &quot;CLI arguments&quot;">​</a></h2><p>Most commands take <code>[brand] [target]</code> — brand (loft, ann) and target (date, path, or operation). Brand defaults to config; target varies by command (date/path for preview/push, campaign prefix for upload, zone for registry). Use <code>make &lt;command&gt; ARGS=&quot;--help&quot;</code> to see per-command args.</p><h2 id="commit" tabindex="-1">commit <a class="header-anchor" href="#commit" aria-label="Permalink to &quot;commit {#commit}&quot;">​</a></h2><p>Save the selected refresh to Git. The commit message is generated from brand, date, and refresh; Git is invoked via an argument list (no shell), so paths and messages are safe from injection. Use after <code>make push</code> and replication.</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="browse" tabindex="-1">browse <a class="header-anchor" href="#browse" aria-label="Permalink to &quot;browse {#browse}&quot;">​</a></h2><p>Interactive file picker for data files in the active refresh (assets/*.json, refresh.json, ocapi-payload.json). Use arrow keys to browse, Enter to select (prints path), q to exit. The <a href="/ocapi-docs.github.io/cli/status.html">status</a> hub also offers a &quot;Browse files&quot; action (data + templates + rendered in one picker).</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> browse</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> browse</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DATE=2026-02-14</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="select" tabindex="-1">select (use status) <a class="header-anchor" href="#select" aria-label="Permalink to &quot;select (use status) {#select}&quot;">​</a></h2><p>There is no <code>make select</code> target. Use <strong><code>make status</code></strong> to open the interactive hub and pick a refresh: <code>make status</code>, <code>make status DATE=2026-02-14</code>, or <code>make status DATE=2026-02-14/r2</code> to pre-select a refresh. Picking sets your <a href="/ocapi-docs.github.io/glossary.html#sticky-selection-active-refresh">sticky selection</a>. For scripted selection, use <code>sfcc select loft DATE=2026-02-14</code> (or <code>ann</code>). See <a href="/ocapi-docs.github.io/cli/status.html">status</a>.</p><h2 id="per-command-pages" tabindex="-1">Per-command pages <a class="header-anchor" href="#per-command-pages" aria-label="Permalink to &quot;Per-command pages&quot;">​</a></h2><ul><li><strong>Producer:</strong> <a href="/ocapi-docs.github.io/cli/status.html">status</a> · <a href="/ocapi-docs.github.io/cli/pull.html">pull</a> · <a href="/ocapi-docs.github.io/cli/preview.html">preview</a> · <a href="/ocapi-docs.github.io/cli/push.html">push</a> · <a href="/ocapi-docs.github.io/cli/replicate.html">replicate</a> · <a href="/ocapi-docs.github.io/cli/email.html">email</a> · <a href="/ocapi-docs.github.io/cli/commit.html">commit</a> · <a href="/ocapi-docs.github.io/cli/browse.html">browse</a> — select: see <a href="#select">above</a>. Sticky selection: <a href="/ocapi-docs.github.io/glossary.html#sticky-selection-active-refresh">Glossary#sticky-selection</a>.</li><li><strong>Dev &amp; Ops:</strong> <a href="/ocapi-docs.github.io/cli/setup.html">setup</a> · <a href="/ocapi-docs.github.io/cli/upload.html">upload</a> · <a href="/ocapi-docs.github.io/cli/delete.html">delete</a> · <a href="/ocapi-docs.github.io/cli/registry.html">registry</a> · <a href="/ocapi-docs.github.io/cli/health.html">health</a> · <a href="/ocapi-docs.github.io/cli/excel.html">excel</a> · <a href="/ocapi-docs.github.io/cli/reports.html">reports</a> · <a href="/ocapi-docs.github.io/cli/validate.html">validate</a></li></ul><p>For full workflow and example output, see <a href="/ocapi-docs.github.io/guides/producer-workflow.html">Producer Workflow</a>. For a walkthrough of blocking errors and approval steps, see <a href="/ocapi-docs.github.io/guides/producer-workflow.html">Producer Workflow</a>.</p>`,27)])])}const u=t(r,[["render",s]]);export{p as __pageData,u as default};
